-- Session dashboard roster; generated by CLI and ordered after its prerequisites.
create or replace function internal.valid_training_block_players(players jsonb)
returns boolean language plpgsql immutable set search_path = '' as $$
declare player jsonb;
begin
  if jsonb_typeof(players) is distinct from 'array' then return false; end if;
  if jsonb_array_length(players) > 80 then return false; end if;
  for player in select value from jsonb_array_elements(players) loop
    if jsonb_typeof(player) is distinct from 'object'
      or jsonb_typeof(player->'name') is distinct from 'string'
      or length(player->>'name') > 120
      or coalesce(player->>'team', '') not in ('blue','red','green','yellow','neutral')
      or (player - array['person_id','name','team','roster_id']) <> '{}'::jsonb then return false; end if;
    if player->>'person_id' is not null and (
      jsonb_typeof(player->'person_id') is distinct from 'string'
      or player->>'person_id' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ) then return false; end if;
  end loop;
  return not exists (select 1 from jsonb_array_elements(players) p
    where p->>'person_id' is not null group by lower(p->>'person_id') having count(*) > 1);
end;
$$;
revoke all on function internal.valid_training_block_players(jsonb) from public, anon, authenticated;

alter table core.training_sessions add column roster jsonb
  check (roster is null or internal.valid_training_block_players(roster));
-- Stable references preserve every existing block assignment, including unnamed players.
update core.training_blocks block set players = coalesce((select jsonb_agg(entry.value || jsonb_build_object(
  'roster_id', coalesce(entry.value->>'person_id', 'anonymous-' || block.id::text || '-' || entry.position::text))
  order by entry.position) from jsonb_array_elements(block.players) with ordinality entry(value,position)), '[]'::jsonb);

create function internal.training_session_roster(event_row core.events)
returns jsonb language plpgsql stable set search_path = '' as $$
declare saved jsonb;
begin
  select roster into saved from core.training_sessions where event_id=event_row.id;
  if saved is not null then return saved; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('roster_id', item.id, 'person_id', item.person_id, 'name', '', 'team', 'blue') order by item.id)
    from (select distinct on (id) id, person_id from (
      select entry->>'roster_id' as id, entry->>'person_id' as person_id
        from core.training_blocks block cross join lateral jsonb_array_elements(block.players) entry where block.event_id=event_row.id
      union all
      select callup.club_person_id::text, callup.club_person_id::text
        from core.callups callup join core.club_people person on person.id=callup.club_person_id and person.club_id=event_row.club_id
        where callup.event_id=event_row.id and callup.state='accepted' and person.status='active'
        and exists(select 1 from core.assignments assignment join core.event_teams relation
          on relation.event_id=event_row.id and relation.club_id=assignment.club_id and relation.team_id=assignment.team_id
          where assignment.club_id=event_row.club_id and assignment.club_person_id=person.id
            and assignment.role_package='player' and assignment.state='active'
            and assignment.starts_at<=event_row.starts_at and (assignment.ends_at is null or assignment.ends_at>event_row.starts_at))
    ) candidates order by id) item), '[]'::jsonb);
end;
$$;
revoke all on function internal.training_session_roster(core.events) from public, anon, authenticated;

create function internal.training_players_json(players jsonb, target_club_id uuid)
returns jsonb language sql stable set search_path = '' as $$
 select coalesce(jsonb_agg(entry.value || jsonb_build_object('name', case when entry.value->>'person_id' is null then '' else coalesce(
   (select left(person.display_name,120) from core.club_people person where person.id=(entry.value->>'person_id')::uuid
     and person.club_id=target_club_id and person.status='active'), '—') end) order by entry.position), '[]'::jsonb)
 from jsonb_array_elements(players) with ordinality entry(value,position)
$$;
revoke all on function internal.training_players_json(jsonb,uuid) from public, anon, authenticated;

create or replace function internal.training_session_json(event_row core.events, can_edit boolean)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare session core.training_sessions;
begin
  select * into session from core.training_sessions where event_id = event_row.id;
  if not can_edit and (session.event_id is null or not session.published) then return null; end if;
  return jsonb_build_object(
    'event_id', event_row.id, 'can_edit', can_edit,
    'roster_saved', session.roster is not null,
    'roster', internal.training_players_json(internal.training_session_roster(event_row),event_row.club_id),
    'title', event_row.title, 'starts_at', event_row.starts_at, 'ends_at', event_row.ends_at,
    'revision', coalesce(session.revision, 0), 'published', coalesce(session.published, false),
    'theme', coalesce(session.theme, coalesce(event_row.training_theme, '')),
    'goal', coalesce(session.goal, ''),
    'event_plan', case when session.event_id is null then nullif(btrim(coalesce(event_row.training_plan, '')), '') end,
    'updated_at', session.updated_at,
    'updated_by', (select nullif(btrim(profile.display_name), '') from core.profiles profile where profile.id = session.updated_by),
    'blocks', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', block.id, 'part', block.part, 'title', block.title, 'minutes', block.minutes,
        'organisation', block.organisation, 'coaching_points', block.coaching_points, 'phase', block.phase,
        'source_kind', block.source_kind, 'source_id', block.source_id, 'players', internal.training_players_json(block.players,event_row.club_id)
      ) order by block.position)
      from core.training_blocks block where block.event_id = event_row.id), '[]'::jsonb)
  );
end;
$$;

create or replace function internal.save_training_session_roster_for_actor(
  target_event_id uuid, expected_revision bigint, session_theme text, session_goal text, is_published boolean,
  session_blocks jsonb, session_roster jsonb
) returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  event_row core.events;
  current_revision bigint;
  block jsonb;
  player jsonb;
  actual_roster jsonb;
  block_position integer := 0;
begin
  event_row := internal.training_session_event(target_event_id);
  if not internal.training_session_can_edit(event_row) then raise insufficient_privilege using message = 'not_allowed'; end if;
  if length(coalesce(session_theme, '')) > 200 or length(coalesce(session_goal, '')) > 2000 or is_published is null
    or jsonb_typeof(coalesce(session_blocks, 'null'::jsonb)) <> 'array' or jsonb_array_length(session_blocks) > 30 then
    raise invalid_parameter_value using message = 'invalid_input';
  end if;
  actual_roster := coalesce(session_roster, internal.training_session_roster(event_row));
  if not internal.valid_training_block_players(actual_roster) then raise invalid_parameter_value using message='invalid_roster'; end if;
  for player in select value from jsonb_array_elements(actual_roster) loop
    if coalesce(player->>'roster_id',player->>'person_id','') !~ '^[a-zA-Z0-9_-]{1,100}$'
      or (player->>'person_id' is not null and coalesce(player->>'roster_id',player->>'person_id') <> player->>'person_id')
      or (player->>'person_id' is null and coalesce(player->>'roster_id','') not like 'anonymous-%') then
      raise invalid_parameter_value using message='invalid_roster'; end if;
    if player->>'person_id' is not null and not exists(
      select 1 from core.assignments assignment join core.club_people person on person.id=assignment.club_person_id and person.club_id=assignment.club_id
      join core.event_teams relation on relation.event_id=event_row.id and relation.club_id=assignment.club_id and relation.team_id=assignment.team_id
      where assignment.club_id=event_row.club_id and assignment.club_person_id=(player->>'person_id')::uuid
        and assignment.state='active' and assignment.role_package='player' and person.status='active'
        and assignment.starts_at<=event_row.starts_at and (assignment.ends_at is null or assignment.ends_at>event_row.starts_at)
    ) then raise invalid_parameter_value using message='invalid_player_reference'; end if;
  end loop;
  if exists(select 1 from jsonb_array_elements(actual_roster) entry group by coalesce(entry->>'roster_id',entry->>'person_id') having count(*)>1) then
    raise invalid_parameter_value using message='duplicate_roster_player'; end if;

  for block in select value from jsonb_array_elements(session_blocks) loop
    if jsonb_typeof(block) <> 'object'
      or coalesce(block->>'part', '') not in ('warmup', 'main', 'finish')
      or length(btrim(coalesce(block->>'title', ''))) not between 1 and 120
      or jsonb_typeof(block->'minutes') is distinct from 'number'
      or (block->>'minutes')::numeric not between 0 and 240 or (block->>'minutes')::numeric <> round((block->>'minutes')::numeric)
      or length(coalesce(block->>'organisation', '')) > 2000 or length(coalesce(block->>'coaching_points', '')) > 2000
      or (block->>'phase' is not null and block->>'phase' not in ('scoring', 'preventing_scoring', 'build_up',
        'preventing_build_up', 'counter', 'regaining', 'attacking_play', 'defending'))
      or coalesce(block->>'source_kind', 'own') not in ('own', 'library') then
      raise invalid_parameter_value using message = 'invalid_input';
    end if;
    if not internal.valid_training_block_players(coalesce(block->'players', '[]'::jsonb)) then
      raise invalid_parameter_value using message = 'invalid_players';
    end if;
    for player in select value from jsonb_array_elements(coalesce(block->'players','[]'::jsonb)) loop
      if not exists(select 1 from jsonb_array_elements(actual_roster) chosen
        where coalesce(chosen->>'roster_id',chosen->>'person_id')=coalesce(player->>'roster_id',player->>'person_id')
          and chosen->>'person_id' is not distinct from player->>'person_id') then
        raise invalid_parameter_value using message='player_not_in_session_roster'; end if;
      if player->>'person_id' is not null and not exists (
        select 1 from core.assignments assignment
        join core.club_people person on person.id = assignment.club_person_id and person.club_id = assignment.club_id
        join core.event_teams relation on relation.event_id = event_row.id and relation.club_id = assignment.club_id
          and relation.team_id = assignment.team_id
        where assignment.club_id = event_row.club_id and assignment.club_person_id = (player->>'person_id')::uuid
          and assignment.state = 'active' and assignment.role_package = 'player' and person.status = 'active'
          and assignment.starts_at <= event_row.starts_at and (assignment.ends_at is null or assignment.ends_at > event_row.starts_at)
      ) then raise invalid_parameter_value using message = 'invalid_player_reference'; end if;
    end loop;
  end loop;
  if exists(select 1 from jsonb_array_elements(session_blocks) with ordinality block_entry(value,position)
    cross join lateral jsonb_array_elements(coalesce(block_entry.value->'players','[]'::jsonb)) player_entry(value)
    group by block_entry.position, coalesce(player_entry.value->>'roster_id',player_entry.value->>'person_id') having count(*)>1) then
    raise invalid_parameter_value using message='duplicate_block_player'; end if;
  perform pg_advisory_xact_lock(hashtextextended(event_row.id::text, 2));
  select revision into current_revision from core.training_sessions where event_id = event_row.id for update;
  if coalesce(current_revision, 0) <> coalesce(expected_revision, -1) then
    raise serialization_failure using message = 'stale_revision';
  end if;
  insert into core.training_sessions (event_id, club_id, team_id, theme, goal, published, revision, updated_by)
  values (event_row.id, event_row.club_id, event_row.owning_team_id, btrim(coalesce(session_theme, '')),
    btrim(coalesce(session_goal, '')), is_published, 1, auth.uid())
  on conflict (event_id) do update set theme = excluded.theme, goal = excluded.goal, published = excluded.published,
    revision = core.training_sessions.revision + 1, updated_at = now(), updated_by = excluded.updated_by;
  delete from core.training_blocks where event_id = event_row.id;
  for block in select value from jsonb_array_elements(session_blocks) loop
    insert into core.training_blocks (event_id, position, part, title, minutes, organisation, coaching_points, phase,
      source_kind, source_id, players)
    values (event_row.id, block_position, block->>'part', btrim(block->>'title'), (block->>'minutes')::integer,
      coalesce(block->>'organisation', ''), coalesce(block->>'coaching_points', ''), block->>'phase',
      coalesce(block->>'source_kind', 'own'),
      case when block->>'source_kind' = 'library' then nullif(block->>'source_id', '')::uuid end,
      coalesce((select jsonb_agg(jsonb_build_object(
        'roster_id', coalesce(entry.value->>'roster_id',entry.value->>'person_id'), 'person_id', entry.value->>'person_id', 'team', entry.value->>'team',
        'name', ''
      ) order by entry.position) from jsonb_array_elements(coalesce(block->'players','[]'::jsonb)) with ordinality entry(value,position)), '[]'::jsonb));
    block_position := block_position + 1;
  end loop;
  update core.training_sessions set roster=coalesce((select jsonb_agg(jsonb_build_object(
    'roster_id', coalesce(entry->>'roster_id',entry->>'person_id'), 'person_id', entry->>'person_id', 'name', '', 'team', 'blue'))
    from jsonb_array_elements(actual_roster) entry), '[]'::jsonb) where event_id=event_row.id;
  return internal.training_session_json(event_row, true);
end;
$$;

-- Keep the old six-argument entry point, but apply the same roster boundary.
create or replace function internal.save_training_session_for_actor(target_event_id uuid, expected_revision bigint,
  session_theme text, session_goal text, is_published boolean, session_blocks jsonb)
returns jsonb language sql security definer set search_path='' as $$
 select internal.save_training_session_roster_for_actor(target_event_id,expected_revision,session_theme,session_goal,is_published,session_blocks,null)
$$;
create function api.save_training_session(target_event_id uuid, expected_revision bigint,
  session_theme text, session_goal text, is_published boolean, session_blocks jsonb, session_roster jsonb)
returns jsonb language sql security invoker set search_path='' as $$
 select internal.save_training_session_roster_for_actor(target_event_id,expected_revision,session_theme,session_goal,is_published,session_blocks,session_roster)
$$;
revoke all on function internal.save_training_session_roster_for_actor(uuid,bigint,text,text,boolean,jsonb,jsonb),
 api.save_training_session(uuid,bigint,text,text,boolean,jsonb,jsonb) from public, anon, authenticated;
grant execute on function internal.save_training_session_roster_for_actor(uuid,bigint,text,text,boolean,jsonb,jsonb),
 api.save_training_session(uuid,bigint,text,text,boolean,jsonb,jsonb) to authenticated;
notify pgrst, 'reload schema';
